<section class="soc-shell min-h-screen"><div class="mx-auto max-w-5xl px-4 py-10 sm:px-6"><a class="text-emerald-400" href="<?= e(url('/security/adaptive')) ?>">&larr; Adaptive deception</a><div class="mt-5 rounded-2xl border border-slate-800 bg-slate-900 p-6"><p class="section-label text-emerald-400">Security session #<?= e((string)$decision['security_session_id']) ?></p><h1 class="mt-2 text-3xl font-semibold"><?= e($decision['current_profile']) ?> deception profile</h1><p class="mt-2 text-slate-400">Assessment <?= e($decision['threat_level']) ?> &middot; <?= e((string)$decision['score']) ?>/100</p><h2 class="mt-8 text-lg font-semibold">Decision and interaction timeline</h2><?php if($decision['events']===[]): ?><p class="mt-3 text-slate-400">No deception decisions for this session.</p><?php else: ?><div class="mt-3 space-y-2"><?php foreach($decision['events'] as $event): ?><div class="rounded border border-slate-800 p-3"><div class="flex justify-between gap-3"><strong><?= e($event['event_type']) ?></strong><span class="text-sm text-slate-500"><?= e($event['created_at']) ?></span></div><p class="mt-1 text-sm text-slate-400"><?= e($event['metadata']['previous_profile'] ?? 'NONE') ?> &rarr; <?= e($event['metadata']['selected_profile'] ?? $event['metadata']['deception_profile'] ?? 'UNSPECIFIED') ?> &middot; <?= e($event['metadata']['selection_reason'] ?? 'observed interaction') ?></p></div><?php endforeach; ?></div><?php endif; ?></div></div></section>
